  def genTestCase(observationKind: ObservationKind.Type, preContainer: Option[String], postContainer: Option[String], testNameSuffix: Option[String]): ST = {
    val tq = "\"\"\""
    val suffix: String =
      if (testNameSuffix.nonEmpty) testNameSuffix.get
      else ""

    observationKind match {
      case navigation_obstacle_awareness_use_supervisor.runtimemonitor.ObservationKind.NavigationObstacleAwarenessUseSupervisorSystem_Instance_supervisorProcess_gpsEvidenceQualifier_postCompute =>
        return (st"""// Begin test cases for NavigationObstacleAwarenessUseSupervisorSystem_Instance_supervisorProcess_gpsEvidenceQualifier_postCompute
                    |
                    |test(s"NavigationObstacleAwarenessUseSupervisorSystem_Instance_supervisorProcess_gpsEvidenceQualifier_postCompute: Check Post-condition$suffix") {
                    |  val preJson: String = st${tq}${preContainer.get}${tq}.render
                    |  val postJson: String = st${tq}${postContainer.get}${tq}.render
                    |  val preContainer = navigation_obstacle_awareness_use_supervisor.JSON.toNavigation_Obstacle_Awareness_Use_SupervisorGpsEvidenceQualifier_supervisorProcess_gpsEvidenceQualifier_PreState_Container_PS(preJson).left
                    |  val postContainer = navigation_obstacle_awareness_use_supervisor.JSON.toNavigation_Obstacle_Awareness_Use_SupervisorGpsEvidenceQualifier_supervisorProcess_gpsEvidenceQualifier_PostState_Container_PS(postJson).left
                    |  if (verbose) {
                    |    println("Pre-State Values:")
                    |    println(s"  $$preContainer")
                    |    println("Post-State Values:")
                    |    println(s"  $$postContainer");
                    |  }
                    |  assert(navigation_obstacle_awareness_use_supervisor.Navigation_Obstacle_Awareness_Use_Supervisor.GpsEvidenceQualifier_supervisorProcess_gpsEvidenceQualifier_GumboX.compute_CEP_Post_Container(preContainer, postContainer))
                    |}
                    |// End test cases for NavigationObstacleAwarenessUseSupervisorSystem_Instance_supervisorProcess_gpsEvidenceQualifier_postCompute""")









      case _ => return st"// TODO ${observationKind}"
    }
  }

